from ortools.linear_solver import pywraplp
import json

def main():
    N = 6
    p = [9, 4, 13, 10, 7, 19]
    alpha = [4, 3, 1, 2, 4, 8]
    beta = [12, 12, 10, 5, 4, 14]

    total_time = sum(p)
    T = 0.60 * total_time

    solver = pywraplp.Solver.CreateSolver('SCIP')
    if not solver:
        print('Could not create solver')
        return

    INF = solver.infinity()

    x = {}
    for i in range(N):
        for j in range(N):
            x[i, j] = solver.BoolVar(f'x[{i},{j}]')

    C = [solver.NumVar(0, INF, f'C[{j}]') for j in range(N)]

    E = [solver.NumVar(0, INF, f'E[{j}]') for j in range(N)]
    L = [solver.NumVar(0, INF, f'L[{j}]') for j in range(N)]

    for i in range(N):
        solver.Add(sum(x[i, j] for j in range(N)) == 1)

    for j in range(N):
        solver.Add(sum(x[i, j] for i in range(N)) == 1)

    solver.Add(C[0] == sum(p[i] * x[i, 0] for i in range(N)))

    for j in range(1, N):
        solver.Add(C[j] == C[j-1] + sum(p[i] * x[i, j] for i in range(N)))

    for j in range(N):
        solver.Add(E[j] >= T - C[j])
        solver.Add(L[j] >= C[j] - T)

    penalty = {}
    for i in range(N):
        for j in range(N):
            penalty[i, j] = solver.NumVar(0, INF, f'penalty[{i},{j}]')

    M = 1000

    for i in range(N):
        for j in range(N):
            solver.Add(penalty[i, j] >= alpha[i] * E[j] + beta[i] * L[j] - M * (1 - x[i, j]))

            solver.Add(penalty[i, j] <= alpha[i] * E[j] + beta[i] * L[j] + M * (1 - x[i, j]))

            solver.Add(penalty[i, j] <= M * x[i, j])

    objective = solver.Sum(penalty[i, j] for i in range(N) for j in range(N))
    solver.Minimize(objective)

    solver.SetTimeLimit(60000)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL or status == pywraplp.Solver.FEASIBLE:
        sequence = []
        for j in range(N):
            for i in range(N):
                if x[i, j].solution_value() > 0.5:
                    sequence.append(i + 1)
                    break

        total_cost = solver.Objective().Value()

        print(json.dumps({
            "server_sequence": sequence,
            "total_cost": total_cost
        }))
    else:
        print(json.dumps({
            "server_sequence": [],
            "total_cost": None
        }))

if __name__ == '__main__':
    main()
